  ('443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$Biologie$$, $$VWO$$, $$Lachgas, geen onschuldige partydrug$$, $$VWO Biologie 2022-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('4e560984-5cf1-48aa-a33a-ecc3f799547c', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$ruim honderd Belgische vrouwen kregen ernstig nierfalen en tumoren door een afslankmiddel met Aristolochia$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context1.png$$,
   $$In tegenstelling tot wat veel mensen denken, zijn natuurgeneesmiddelen niet altijd veilig. Zo kunnen sommige Chinese kruidenpreparaten met Aristolochia ernstige nierschade veroorzaken.
Ruim honderd Belgische vrouwen die in de jaren 90 een bepaald afslankmiddel op basis van kruiden hadden gebruikt, ontwikkelden ernstig nierfalen. De oorzaak was aristolochiazuur, afkomstig van de Aristolochia-plant die in het middel verwerkt was. Bij sommige vrouwen was de nierschade zo groot dat een niertransplantatie nodig was. Bij anderen werden jaren later tumoren in de urinewegen aangetroffen.$$, 'inline'),
  ('ec05b0e9-bf05-4d31-a9a9-292aa10e3022', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$diuretische werking van aristolochiazuur in het afslankmiddel$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context2.png$$,
   $$De toepassing van Aristolochia in afslankmiddelen berust op de diuretische (vochtafdrijvende) werking van aristolochiazuur.$$, 'inline'),
  ('8022750d-1818-4094-b880-d6edae51ff52', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$werkingsmechanisme van aristolochiazuur nog onbekend; mogelijk via een hypofysehormoon$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context3.png$$,
   $$Het werkingsmechanisme van aristolochiazuur is nog niet helemaal bekend. Aanvankelijk werd aangenomen dat het vochtafdrijvend werkt door de afgifte van een bepaald hypofysehormoon te beïnvloeden.$$, 'inline'),
  ('43d2cc57-899c-4a4c-bfcd-c9805062b7af', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$aristolochiazuur verlaagt de permeabiliteit van de verzamelbuisjes voor ureum$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context4.png$$,
   $$Inmiddels neemt men aan dat aristolochiazuur diuretisch werkt doordat deze stof de permeabiliteit van de verzamelbuisjes voor ureum verlaagt.$$, 'inline'),
  ('9bd95536-3cf1-4e18-826c-8c5d65a4f805', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$nierschade bij de Belgische vrouwen ontdekt via bloedonderzoek: bloedarmoede en gekrompen, vervormde nieren$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context5.png$$,
   $$De nierschade bij de Belgische vrouwen werd meestal toevallig ontdekt na een routine-bloedonderzoek. Het bloedonderzoek toonde bij deze vrouwen vaak ernstige bloedarmoede aan. Bij nader onderzoek bleken de nieren gekrompen en vervormd te zijn.$$, 'inline'),
  ('3415f219-f569-4110-8be7-3629c5237117', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$aristolochiazuur wordt omgezet in aristolactam, dat als DNA-adduct aan het DNA bindt en tot een verkeerde base bij replicatie kan leiden$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context6.png$$,
   $$Van aristolochiazuur is bekend dat het mutaties kan veroorzaken. Daarom was het aannemelijk dat de tumoren in de nieren van de Belgische vrouwen te wijten waren aan het gebruik van het afslankmiddel met Aristolochia.
Aristolochiazuur wordt door cellen van de nier, maar ook door levercellen, omgezet in de stof aristolactam, dat bindt aan bepaalde basen van het DNA. Zo''n stof die gebonden is aan het DNA wordt een DNA-adduct genoemd. Op de plaats van zo''n adduct kan bij replicatie een verkeerde base worden ingebouwd in de nieuwe DNA-streng.$$, 'inline'),
  ('d20abf99-8b1c-495a-94b2-fc2ce3a68c3a', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$in de uitwerkbijlage is een DNA-nucleotide met een DNA-adduct afgebeeld$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context7.png$$,
   $$In de uitwerkbijlage is een DNA-nucleotide afgebeeld met daaraan gebonden een DNA-adduct dat ontstaat door gebruik van Aristolochia.$$, 'inline'),
  ('2fbed946-eec8-4ed1-a645-5417860a1b4d', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$DNA-adducten die aan proto-oncogenen of tumorsuppressorgenen binden kunnen kanker veroorzaken; TP53 codeert voor tumorsuppressor p53 die bij DNA-schade apoptose activeert$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context8.png$$,
   $$Wanneer DNA-adducten aan basen van proto-oncogenen of tumorsuppressor-genen binden, kan kanker ontstaan. Een van de genen die werd onderzocht bij de Belgische vrouwen is het TP53-gen, dat codeert voor tumorsuppressor p53. Dit eiwit is betrokken bij de controle van het DNA tijdens de celcyclus. Indien er grote schade aan het DNA ontstaat, zet p53 aan tot apoptose.$$, 'inline'),
  ('f86e23ce-7daa-46e2-b41e-bf54e3ff4c42', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$afbeelding 1: locaties van 47 mutaties in exons en 12 mutaties in splice-plaatsen van het TP53-gen bij 42 patiënten$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context9.png$$,
   $$Het TP53-gen omvat 11 exons en 10 introns. Afbeelding 1 geeft de locaties weer van alle mutaties die gevonden zijn in het TP53-gen in niertumoren van 42 patiënten die kruidenpreparaten met Aristolochia gebruikt hebben. Er werden 47 mutaties gevonden in de exons, vooral in basenkoppel A-T, maar ook in het koppel G-C. Deze mutaties zijn weergegeven met gesloten pijlen. De plaats van de introns is in de afbeelding alleen met een nummer aangegeven, met daarbij als driehoekjes de 12 mutaties die werden gevonden in de splice-plaatsen van introns. Splice-plaatsen markeren het begin en eind van een intron. Mutaties binnen de introns zelf zijn niet onderzocht.$$, 'inline'),
  ('13cd86fd-38a7-4c3d-9df9-860282ca1e2b', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$drie beweringen over de mutaties in afbeelding 1$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context10.png$$,
   $$Over de resultaten in afbeelding 1 worden drie beweringen gedaan:
1 De mutaties in de exons zijn allemaal puntmutaties.
2 De mutaties in de exons zijn allemaal het gevolg van aristolochiazuur.
3 De introns zijn korter dan de exons.$$, 'inline'),
  ('a1ac8e67-1efa-4cfd-9508-08df38f03281', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$twee methoden om het risico op kanker aan de urinewegen te bepalen: aristolactam-adducten of ''A-T naar T-A''-mutaties tellen$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context11.png$$,
   $$Vrouwen die kruidenpreparaten met Aristolochia hebben gebruikt, weten niet precies hoeveel aristolochiazuur ze hebben binnengekregen.
Om te bepalen in hoeverre zij risico lopen op het ontwikkelen van kanker aan de urinewegen, kunnen twee methoden worden toegepast:
1 in het DNA van cellen van de urinewegen het aantal aristolactam-adducten bepalen
2 in het DNA van cellen van de urinewegen het aantal ''A-T naar T-A''-mutaties bepalen
Ga ervan uit dat beide methoden even betrouwbaar zijn; ze zijn echter niet even valide.$$, 'inline'),
  ('f3748db0-f9b2-4221-adce-32ca0fc0e3a4', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', $$uitwerkbijlage bij vraag 5: DNA-nucleotide met daaraan een DNA-adduct$$,
   $$biologie-vwo-2022-i-gevaarlijk-afslankmiddel-context12.png$$,
   $$Uitwerkbijlage bij vraag 5: een DNA-nucleotide (met fosfaatgroep en suikergroep) is afgebeeld met daaraan gebonden de stikstofbase, die op zijn beurt gebonden is aan het DNA-adduct (een ringsysteem met een substituent R). Onder de afbeelding is ruimte om het adduct te omcirkelen en de naam van de stikstofbase te noteren.$$, 'uitwerkbijlage'),
  ('a8fd4502-08b5-45cb-a00b-86c28c23d4b8', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$zeegrasvelden dragen bij aan biodiversiteit; van de oorspronkelijke 15.000 hectare in de Waddenzee is nog maar vijf hectare over$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context1.png$$,
   $$Zeegrasvelden zijn ecosystemen die bijdragen aan een grote biodiversiteit in kustgebieden. Van de 15.000 hectare zeegras die oorspronkelijk in de Nederlandse Waddenzee aanwezig was, is nu nog maar zo''n vijf hectare over. De Waddenvereniging, Rijkswaterstaat en Natuurmonumenten proberen nu de zeegrasvelden weer te herstellen.$$, 'inline'),
  ('28f757be-4c36-48bd-b0b8-4f71bc6c0385', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$flexibele eenjarige en robuuste meerjarige variant van groot zeegras met hun zones (afbeelding 1 en 2); delen van zeegras (afbeelding 3)$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context2.png$$,
   $$Groot zeegras (Zostera marina) is een zaadplant die permanent in brak en zout water kan leven. Groot zeegras kent twee varianten: een flexibele eenjarige variant en een robuuste variant die meestal meerjarig is. Deze varianten komen elk in een eigen zone voor. Door de getijdenverschillen komt de flexibele variant regelmatig droog te liggen (afbeelding 1); de robuuste variant is permanent ondergedoken (afbeelding 2).
In afbeelding 3 zijn verschillende delen van zeegras aangegeven.$$, 'inline'),
  ('43825324-d306-4413-a89f-8e399d8fcaf2', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$robuuste variant stierf rond 1930 uit door een ziekte; herintroductie vereist minder sleepnetvisserij en eutrofiëring$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context3.png$$,
   $$Als gevolg van een wereldwijd optredende ziekte, stierf de robuuste variant van groot zeegras rond 1930 in de Nederlandse Waddenzee uit. Herintroductie van de robuuste variant van groot zeegras is alleen mogelijk als zowel de visserij met sleepnetten als de eutrofiëring van het water wordt beperkt.$$, 'inline'),
  ('b564fd5c-0012-46c4-a355-af847f3df07f', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$flexibele variant plant zich voort via zaden, de robuuste variant vooral via wortelstokken$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context4.png$$,
   $$Flexibel zeegras plant zich voornamelijk voort door middel van zaden, terwijl de robuuste variant zich vooral uitbreidt via wortelstokken.$$, 'inline'),
  ('bf2c3cbe-0034-4eae-88e2-03d50c00e10f', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$afbeelding 4: zuurstoftransport naar de wortels overdag en zuurstoftekort ''s nachts bij groot zeegras$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context5.png$$,
   $$Zowel de bladeren als de wortels van zeegras hebben luchtruimtes. Overdag wordt de geproduceerde zuurstof naar de wortels en wortelstokken getransporteerd en wordt een deel van deze zuurstof aan het sediment afgegeven (afbeelding 4). ''s Nachts raakt de zuurstof in het sediment snel op.$$, 'inline'),
  ('4ee06987-c5c3-40b7-a7ff-237d6f11b2e5', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$vier deelprocessen van de dissimilatie bij zuurstoftekort in de wortelcellen$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context6.png$$,
   $$In de cellen van de wortel leidt het zuurstoftekort ''s nachts tot de productie van ethanol.
Enkele deelprocessen van de dissimilatie zijn:
1 oxidatieve fosforylering
2 omzetting van NADH in NAD⁺
3 omzetting van NAD⁺ in NADH
4 vorming van ATP$$, 'inline'),
  ('d295315d-8aec-4d0f-8e3f-c276d95b82e9', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$afbeelding 5: aantal opgekomen zeegrasplantjes na zaaien op vier locaties; mogelijke oorzaken van het slechte resultaat zijn zeewier, golfslag en wadpieren$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context7.png$$,
   $$Een aantal jaren achtereen zaaiden vrijwilligers op vier percelen in de Nederlandse Waddenzee zaden van groot zeegras, geoogst uit het Duitse deel van de Waddenzee waar nog grote velden met groot zeegras zijn.
De getallen in afbeelding 5 geven aan hoeveel plantjes er zijn opgekomen.
De zaden ontkiemen wel, maar er vestigen zich onvoldoende planten om een zeegraspopulatie te verkrijgen die zichzelf in stand kan houden. Onderzoekers noemen als mogelijke oorzaken van het slechte resultaat: zeewier, golfslag en de aanwezigheid van wadpieren.$$, 'inline'),
  ('9bd2fe9a-88f2-40f3-8d21-1b3822e221d0', '3b9f58ce-c33f-4430-94e5-84c39fd646fc', $$proefopstelling met acht proefvlakken per locatie en tabel 1 met combinaties van zeewier, golfslag en wadpieren; wijze waarop elke factor werd tegengehouden$$,
   $$biologie-vwo-2022-i-zeegrasherstel-in-de-waddenzee-context8.png$$,
   $$Om informatie te krijgen over de invloed van de drie factoren in de Waddenzee (zeewier, golfslag en wadpieren), is een proefopstelling aangelegd op vier locaties met zeegras. Op elke locatie werden acht proefvlakken uitgezet: zeven proefvlakken kregen elk een andere combinatie van behandelingen; één proefvlak diende als controle (tabel 1).
De verschillende behandelingen werden als volgt gerealiseerd:
− Zeewier werd tegengehouden door een kooi van fijn gaas te plaatsen.
− Golfslag werd tegengehouden door zandzakken te leggen.
− Wadpieren werden tegengehouden door gaas op de zeebodem aan te brengen.$$, 'inline'),
  ('2ac347e8-dce9-4a40-8ac5-ae0bb3abe4bc', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$tijgermug lift mee op bamboeplanten en autobanden en kan virusziekten zoals chikungunya overbrengen$$,
   $$biologie-vwo-2022-i-tijgermuggen-context1.png$$,
   $$Al jarenlang lift de tijgermug mee op bamboeplanten en autobanden die vanuit Azië geïmporteerd worden. Kan deze overbrenger van virusziekten zoals chikungunya, ook in Nederland problemen geven?$$, 'inline'),
  ('f06840c6-8970-4f76-8689-d1be07e400cd', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$de Aziatische tijgermug legt diapauze-eitjes om de winter te overleven; larven leven van plantenresten in water (afbeelding 1 en 2), volwassenen leven van nectar en vrouwtjes zuigen bloed voor eiproductie$$,
   $$biologie-vwo-2022-i-tijgermuggen-context2.png$$,
   $$De Aziatische tijgermug (Aedes albopictus) komt oorspronkelijk uit Oost-Azië, maar heeft zich inmiddels gevestigd in delen van Noord- en Zuid-Amerika, Afrika en Zuid-Europa. In gematigde streken overleven volwassen tijgermuggen de winter niet. Toch kan de soort daar overleven omdat tijgermugvrouwtjes voor de winter diapauze-eitjes kunnen leggen. Diapauze-eitjes komen niet snel uit en kunnen kou en droogte overleven.
De eitjes worden afgezet vlak boven een klein waterreservoir dat dode plantenresten bevat. In het voorjaar komen de larven uit de eitjes en leven van de plantenresten in het water. Afbeelding 1 toont de oorspronkelijke larvenbroedplaats: holle bamboestengels in Azië. Afbeelding 2 toont een nieuwe larvenbroedplaats: plastic containers in Frankrijk.
Volwassen mannetjes en vrouwtjes leven van nectar uit bloemen. In mei beginnen de vrouwtjes met het steken van zoogdieren en vogels om extra voedingstoffen te krijgen voor het leggen van gewone eitjes. Onder gunstige omstandigheden ontstaat er zo elke drie weken een nieuwe generatie tijgermuggen.$$, 'inline'),
  ('5d4cda3e-0bc5-4f7f-8764-f628f00848c9', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$vijf mogelijke trofische niveaus van de tijgermug$$,
   $$biologie-vwo-2022-i-tijgermuggen-context3.png$$,
   $$Tijdens haar levenscyclus behoort een tijgermugvrouwtje tot verschillende trofische niveaus. Enkele trofische niveaus zijn:
1 consument van de 1e orde
2 consument van de 2e orde
3 consument van de 3e orde
4 producent
5 reducent$$, 'inline'),
  ('4189c986-7f2c-41fa-949f-70a8916bc68b', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$daglengte en temperatuur kunnen het invallen van de winter aankondigen; tijgermuggen gebruiken vooral de daglengte$$,
   $$biologie-vwo-2022-i-tijgermuggen-context4.png$$,
   $$Twee abiotische factoren die kunnen wijzen op het invallen van de winter, zijn daglengte en temperatuur. Tijgermuggen blijken vooral de daglengte te gebruiken om het moment te bepalen waarop ze diapauze-eitjes gaan leggen.$$, 'inline'),
  ('97df9255-a8b7-49fa-91a3-5a9f8d8a6382', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$afbeelding 3: kritische fotoperiode van tijgermugpopulaties in de VS en Japan in 1988 en 2008, gemeten over een breedtegraadgebied van 26° tot 42° NB$$,
   $$biologie-vwo-2022-i-tijgermuggen-context5.png$$,
   $$In 1985 werd voor het eerst een grote hoeveelheid tijgermuggen gezien in Texas (VS), vermoedelijk afkomstig uit een container autobanden uit Japan. Geholpen door het transport van de autobanden kon de tijgermug zich over een groot deel van Noord-Amerika verspreiden.
Kort na deze invasie in Noord-Amerika hebben onderzoekers de ''kritische fotoperiode'' bepaald van tijgermugpopulaties uit de VS en Japan. De kritische fotoperiode is de daglengte die in het najaar bij 50% van de vrouwtjes leidt tot de productie van diapauze-eitjes.
In beide landen werden tijgermuggen verzameld in een gebied dat zich uitstrekt van zuid naar noord (van 26° tot 42° noorderbreedte). De resultaten van dit onderzoek zijn weergegeven in afbeelding 3, diagram 1. Twintig jaar later is het onderzoek opnieuw uitgevoerd. De resultaten hiervan zijn weergegeven in diagram 2.$$, 'inline'),
  ('44937b36-e9f9-499c-af47-7d0634cf1567', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$drie beweringen over de resultaten van het fotoperiode-onderzoek in afbeelding 3$$,
   $$biologie-vwo-2022-i-tijgermuggen-context6.png$$,
   $$Over de resultaten van de onderzoeken worden drie beweringen gedaan:
1 In 2008 legden tijgermuggen in de VS gemiddeld later in het jaar diapauze-eitjes dan in 1988.
2 Populaties die in Noord-Amerika of Japan zuidelijker leven dan 26° NB kunnen geen diapauze-eitjes leggen.
3 De Noord-Amerikaanse tijgermuggen zijn afstammelingen van een Japanse populatie uit een gematigde regio, noordelijker dan 30° NB.$$, 'inline'),
  ('5aba2c5c-aa6c-49ae-a977-9794c6a74ccb', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$afbeelding 4: symbiotische relaties tussen mens, tijgermug en het chikungunya-virus$$,
   $$biologie-vwo-2022-i-tijgermuggen-context7.png$$,
   $$Als een tijgermug bloed zuigt bij iemand die het chikungunya-virus draagt, dan wordt deze mug drager van het virus. De mug heeft hier geen last van. Het virus kan vervolgens met het muggenspeeksel in elke persoon terechtkomen die daarna door de mug gestoken wordt. Op deze manier is het virus sinds 2013 in het Caribisch deel van ons koninkrijk verspreid en leidt daar tot uitbraken van de ziekte chikungunya, die ernstig is voor mensen.
Veel van de virusziekten die de tijgermug overbrengt, kunnen nog niet genezen worden en vaccins ontbreken nog.
Muggenexpert Bart Knols heeft een stof gevonden die bij een uitbraak van zo''n virusziekte ingezet kan worden om verdere besmetting in te dammen. Het gaat om een middel dat gebruikt wordt om honden te ontvlooien. Knols slikte de werkzame stof en binnen een uur vielen alle muggen die hem staken dood neer, en dat 18 uur lang.
In afbeelding 4 zijn de symbiotische relaties tussen mens, tijgermug en het chikungunya-virus weergegeven met nummers.$$, 'inline'),
  ('a74772ed-8b94-489d-9361-42bd4e4da7c9', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$muggenexpert Bart Knols ontdekte een tegen tijgermuggen werkzaam vlooienmiddel dat muggen 18 uur lang doodt$$,
   $$biologie-vwo-2022-i-tijgermuggen-context8.png$$,
   $$Veel van de virusziekten die de tijgermug overbrengt, kunnen nog niet genezen worden en vaccins ontbreken nog.
Muggenexpert Bart Knols heeft een stof gevonden die bij een uitbraak van zo''n virusziekte ingezet kan worden om verdere besmetting in te dammen. Het gaat om een middel dat gebruikt wordt om honden te ontvlooien. Knols slikte de werkzame stof en binnen een uur vielen alle muggen die hem staken dood neer, en dat 18 uur lang.$$, 'inline'),
  ('eab6b057-8de0-44ca-b5f6-8cd39c5ee654', '104d8ccc-4a76-44e1-bb18-32d8375a537b', $$het vlooienmiddel is alleen goedgekeurd voor honden; voor gebruik bij mensen is meer onderzoek nodig$$,
   $$biologie-vwo-2022-i-tijgermuggen-context9.png$$,
   $$Het vlooienmiddel van Knols is op de markt gebracht voor gebruik bij honden. Het middel mag pas verkocht worden voor gebruik bij mensen als eerst meer onderzoek is gedaan.$$, 'inline'),
  ('86de879a-ee96-45de-898a-abdf62db285a', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$de mens is een van de weinige zoogdieren die menstrueert; evolutiebiologen onderzoeken het ontstaan hiervan$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context1.png$$,
   $$De mens is een van de weinige zoogdieren die menstrueert. Evolutiebiologen onderzoeken hoe dit in de evolutie is ontstaan.$$, 'inline'),
  ('f4db125c-7d10-4f08-a943-bf0c04f0d578', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$decidualisatie: vorming van de decidua voor innesteling van het embryo; bij niet-menstruerende zoogdieren pas na aanwezigheid van een embryo, bij menstruerende zoogdieren spontaan door progesteron van het geel lichaam$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context2.png$$,
   $$Bij zoogdieren wordt tijdens de rijping van eicellen in de eierstokken het baarmoederslijmvlies dikker door de invloed van oestrogeen. Het gereedmaken van het verdikte baarmoederslijmvlies voor de innesteling van een embryo wordt bij niet-menstruerende zoogdieren pas in gang gezet als een embryo in de baarmoeder aanwezig is. De baarmoederslijmvliescellen van de moeder worden dan aangezet tot decidualisatie. Dit is het vormen van een cellaag (de decidua) waarin het embryo zich kan innestelen. Als de innesteling uitblijft, wordt dit verdikte baarmoederslijmvlies niet afgestoten maar geabsorbeerd. Er volgt dus geen menstruatie.
Bij menstruerende zoogdieren begint de vorming van de decidua ''vanzelf'': het progesteron dat door het geel lichaam wordt afgegeven, veroorzaakt de celdifferentiatie in het baarmoederslijmvlies. Dit wordt spontane decidualisatie genoemd. Bij de menstruatie wordt de decidua afgescheiden.$$, 'inline'),
  ('d339c58a-02a5-444c-a407-02953a8948d2', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$afbeelding 1: fylogenetische stamboom van zoogdieren met aanduiding welke soorten wel, niet, of onbekend menstrueren$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context3.png$$,
   $$Menstruatie is relatief recent in de evolutie ontstaan. In afbeelding 1 is in een fylogenetische stamboom van een groot aantal zoogdieren aangegeven of ze wel of niet menstrueren of dat dat niet bekend is.$$, 'inline'),
  ('32df072b-26ff-460b-b0ce-4a0ae5513eab', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$drie beweringen over de fylogenetische stamboom in afbeelding 1$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context4.png$$,
   $$Drie beweringen over de fylogenetische stamboom in afbeelding 1 zijn:
1 Menstruatie is in de evolutie ten minste drie keer onafhankelijk ontstaan.
2 Tijdens de evolutie van primaten is het menstrueren in ten minste één afstammingslijn weer verloren gegaan.
3 Menstruerende vleermuizen zijn meer verwant aan primaten dan niet-menstruerende vleermuizen.$$, 'inline'),
  ('1c837751-5734-4b8a-ab35-204e2fcb60bf', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$onderzoekers wekten bij huismuizen een menstruatie op via een schijnzwangerschap met een onvruchtbaar mannetje en het bekrassen van het baarmoederslijmvlies$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context5.png$$,
   $$Huismuizen menstrueren niet (afbeelding 1). Het is onderzoekers echter wel gelukt een menstruatie bij huismuizen op te wekken. Hiervoor lieten ze een huismuisvrouwtje paren met een onvruchtbaar huismuismannetje. Hierdoor ontstond een schijnzwangerschap: het geel lichaam geeft progesteron af, waardoor kenmerken van een zwangerschap ontstaan. Tijdens deze schijnzwangerschap werd het oppervlak van het baarmoederslijmvlies heel voorzichtig bekrast, waardoor decidualisatie optrad. Na tien dagen eindigde de schijnzwangerschap en trad er bij het huismuisvrouwtje een bloeding uit de baarmoeder op.$$, 'inline'),
  ('9ca51619-517f-4c70-9c2d-2a8e69d55ed2', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$de bloeding bij het huismuisvrouwtje en de menstruatie bij de mens worden op dezelfde manier in gang gezet$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context6.png$$,
   $$De bloeding bij dit huismuisvrouwtje en de maandelijkse menstruatie bij de mens worden op dezelfde manier in gang gezet.$$, 'inline'),
  ('ea5c45c6-e3a8-4bdf-a536-5491699d6e34', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$mogelijk evolutionair verband tussen bloeden na een schijnzwangerschap bij de huismuis en menstruatie bij primaten$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context7.png$$,
   $$Sommige wetenschappers zien een evolutionair verband tussen de bloeding na een schijnzwangerschap bij de huismuis, en de menstruatie bij primaten. De eigenschap menstruatie zou dan zijn ontstaan uit de eigenschap bloeden na schijnzwangerschap.$$, 'inline'),
  ('f8e6d07b-1120-4409-bff9-2d8ca39731a4', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$evolutionaire verklaring voor spontane decidualisatie: de moeder beschermt zich tegen het evolutionaire moeder-foetus-conflict, waarbij de foetus via de placenta zo veel mogelijk voedingsstoffen probeert te onttrekken$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context8.png$$,
   $$Een evolutionaire verklaring voor het ontstaan van spontane decidualisatie is dat de moeder zich hiermee beschermt tegen het embryo. Doordat moeder en foetus geen identiek genenpakket hebben, zijn hun belangen evolutionair gezien verschillend. De foetus probeert via de placenta zo veel mogelijk voedingsstoffen aan de moeder te onttrekken. Het belang van de moeder is investeren in de groeiende foetus, maar ook in toekomstige kinderen.$$, 'inline'),
  ('3e1e71d0-0bb7-4ef6-8d58-dc987793bb04', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$twee veranderingen tijdens innesteling en vroege zwangerschap: verlies van spierweefsel in de slagadertjes van de decidua en verminderde insulinegevoeligheid van de moeder$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context9.png$$,
   $$Op verschillende organisatieniveaus komt het evolutionaire moeder-foetus-conflict naar voren. Twee veranderingen tijdens innesteling en vroege zwangerschap zijn:
1 De slagadertjes in de decidua van de moeder verliezen hun spierweefsel.
2 Placentahormonen maken de moeder minder gevoelig voor insuline.$$, 'inline'),
  ('511e3e61-26bf-49bf-bb77-831e2c09de51', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$alternatieve verklaring voor spontane decidualisatie: de decidua beoordeelt de kwaliteit van het embryo en remt innesteling van embryo''s met grote chromosomale afwijkingen, wat tot een miskraam kan leiden$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context10.png$$,
   $$Een andere verklaring voor het ontstaan van spontane decidualisatie is dat de cellen van de decidua de kwaliteit van het embryo ''beoordelen''. De innesteling van embryo''s met grote chromosomale afwijkingen wordt geremd, waarna de decidua kan worden afgestoten: een miskraam. Dit gebeurt naar schatting met 30 tot 60% van de embryo''s.$$, 'inline'),
  ('8ed7f5ef-2f47-4c5f-9718-ea8cfdeb141c', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$afbeelding 2: signaalcascade van second messenger cAMP die bij menstruerende en niet-menstruerende zoogdieren leidt tot differentiatie van baarmoederslijmvliescellen tot decidua-cellen$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context11.png$$,
   $$De vorming van de decidua wordt bij niet-menstruerende zoogdieren veroorzaakt doordat het embryo via een aantal tussenstappen zorgt voor een toename van de second messenger cAMP in de cellen van het baarmoederslijmvlies, die daardoor differentiëren tot decidua-cellen.
Bij menstruerende zoogdieren leidt progesteronproductie tijdens de maandelijkse cyclus tot de toename van cAMP en de daaropvolgende celdifferentiatie van de baarmoederslijmvliescellen.
In afbeelding 2 is deze signaalcascade schematisch weergegeven.$$, 'inline'),
  ('77533aa9-ca7c-4b9f-a261-30cb40e9069f', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$drie uitspraken die de werking van progesteron in verband brengen met een toename van cAMP in baarmoederslijmvliescellen$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context12.png$$,
   $$Drie uitspraken die de werking van progesteron bij menstruerende zoogdieren in verband brengen met een toename van cAMP in baarmoederslijmvliescellen zijn:
1 Progesteron vormt met de membraanreceptor een complex dat aan het DNA bindt en zo de expressie van cAMP verhoogt.
2 Progesteron zet bepaalde cellen aan tot de afgifte van een signaalstof die bindt aan de membraanreceptor op baarmoederslijmvliescellen.
3 Progesteron veroorzaakt in baarmoederslijmvliescellen verminderde expressie van het enzym adenylcyclase.$$, 'inline'),
  ('a77f4347-c694-490f-aaa5-0eeb30b500de', '9fad5984-b9e5-42a4-8063-008d7c4b3ef9', $$tijdens zwangerschap en zoogperiode ligt de menstruatiecyclus stil; het zuigen van het jong beïnvloedt de afgifte van GnRH en LH bij de moeder$$,
   $$biologie-vwo-2022-i-evolutie-van-de-menstruatie-context13.png$$,
   $$Tijdens de zwangerschap en de daaropvolgende zoogperiode ligt de menstruatiecyclus van menstruerende zoogdieren stil. Het zuigen van het jong beïnvloedt de afgifte van GnRH en LH bij het moederdier.$$, 'inline'),
  ('ac5fe094-fab1-4734-8d0d-fb5d391d6e7c', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$vwo-scholier Lia liep ernstige zenuwschade op door lachgasgebruik$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context1.png$$,
   $$Lachgas (N₂O) wordt door jongeren steeds vaker gebruikt als partydrug. Zij beschouwen het als een relatief onschadelijk middel dat je een lachkick bezorgt. Vwo-scholier Lia liep ernstige zenuwschade op door het gebruik van lachgas.$$, 'inline'),
  ('48892ca5-c0ae-449b-bd3c-b508786a8155', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$bij lachgasgebruik wordt een ballon met het gas gevuld en ingeademd; lachgas blokkeert NMDA-receptoren en veroorzaakt tijdelijk zuurstofgebrek in de hersenen$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context2.png$$,
   $$Bij lachgasgebruik wordt een ballon gevuld met het gas. Vervolgens wordt een paar keer in- en uitgeademd in de ballon. Hierdoor ontstaat een kortdurend vrolijk gevoel. Dit gevoel ontstaat waarschijnlijk doordat lachgas NMDA-receptoren in synapsen in de hersenen blokkeert. Er ontstaat ook duizeligheid door een tijdelijk zuurstofgebrek in de hersenen.$$, 'inline'),
  ('d60c6b1b-9ade-4ebd-9f0c-6e9a21d6c7d1', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$de NMDA-receptor is een ionkanaal dat door gelijktijdige binding van glutaminezuur en glycine excitatie van het postsynaptisch neuron veroorzaakt$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context3.png$$,
   $$De NMDA-receptor is een ionkanaal dat geactiveerd wordt als glutaminezuur en glycine er tegelijk aan binden. Geactiveerde NMDA-receptoren veroorzaken excitatie van het postsynaptisch neuron.$$, 'inline'),
  ('5872d286-0719-4c45-a9ce-e8021cce32ed', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$N₂O werkt snel maar kortdurend; zes bloedvaten van opname tot effectplaats$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context4.png$$,
   $$N₂O werkt snel. Binnen een minuut is het effect op de hersenen merkbaar, maar dit effect is even snel alweer voorbij.
Enkele bloedvaten zijn:
1 aorta
2 halsader
3 halsslagader
4 longader
5 longslagader
6 onderste holle ader$$, 'inline'),
  ('a693b8bf-6bd6-4b8f-8075-53ef5a48b1e4', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$door zuurstofloze lucht in de ballon daalt de pO₂ in de longen en stijgt de pCO₂$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context5.png$$,
   $$Doordat de lucht in de ballon geen zuurstof bevat, daalt tijdens het in- en uitademen in de ballon de pO₂ in de longen naar ongeveer 6 kPa. Bovendien stijgt het koolstofdioxidegehalte (pCO₂) in de longen.$$, 'inline'),
  ('017d1f42-4552-491e-b4e2-fdaa02d4a261', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$combinatie van lachgas en alcohol kan de ademreflex levensgevaarlijk onderdrukken doordat alcohol het ademcentrum en lachgas de chemoreceptoren onderdrukt$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context6.png$$,
   $$Lia gebruikte lachgas gelukkig nooit samen met alcohol. De combinatie van lachgas en alcohol kan namelijk leiden tot een levensgevaarlijke onderdrukking van de ademreflex. Alcohol onderdrukt het ademcentrum en lachgas onderdrukt de respons van de betrokken chemoreceptoren.$$, 'inline'),
  ('7f529d52-1b1e-4e9f-af7c-cafb398a94d5', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$Lia kreeg minder gevoel in haar benen en moeite met lopen; de huisarts verwees haar naar een neuroloog die een probleem in de impulsgeleiding door aantasting van de myelineschedes vermoedde$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context7.png$$,
   $$Het is niet altijd meteen duidelijk dat zenuwschade het gevolg kan zijn van lachgasgebruik. Lia kreeg minder gevoel in haar benen en ze kreeg moeite met lopen. Toen ze met deze klachten bij haar huisarts kwam, verwees die haar door naar een neuroloog. De neuroloog onderzocht haar beenreflexen en vermoedde een probleem in de impulsgeleiding als gevolg van aantasting van de myelineschedes. Lia vertelde niet over haar lachgasgebruik.$$, 'inline'),
  ('a355e6c5-17d8-4154-bad6-23f14e0898d9', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$afbeelding 1: plaatsen van stimulering en twee sensoren waarmee de neuroloog de zenuwgeleiding in het been van Lia testte; de impulsgeleiding bleek bij Lia verstoord$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context8.png$$,
   $$De neuroloog testte de geleiding van de zenuwen in het been door op een bepaalde plaats de zenuw te stimuleren en met sensoren te meten wanneer de opgewekte impuls op een andere plaats aankomt. In afbeelding 1 zijn de plaatsen van de twee sensoren en de plaats van stimulering aangegeven.
Uit de metingen bleek dat bij Lia de impulsgeleiding was verstoord. De impulsen komen bij Lia later aan dan bij iemand bij wie de myelineschedes wel goed functioneren.$$, 'inline'),
  ('9c8cc55f-3a89-40f7-8d86-a4ccd3e630d7', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$het syndroom van Guillain-Barré is een auto-immuunreactie tegen myeline; afbeelding 2 toont hoe antistoffen en macrofagen de cellen van Schwann afbreken$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context9.png$$,
   $$Op basis van de verstoorde impulsgeleiding en bloedonderzoek vermoedde de neuroloog bij Lia het syndroom van Guillain-Barré, een auto-immuunreactie tegen myeline. Bij deze ontstekingsreactie worden antistoffen gevormd die leiden tot de afbraak van de cellen van Schwann door macrofagen (afbeelding 2).$$, 'inline'),
  ('def78277-c985-4f3f-8b55-c2817a73b38b', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$Lia werd vijf dagen behandeld met intraveneus immuunglobuline (IVIg), dat de productie van cytokine IL-2 door T-helpercellen remt$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context10.png$$,
   $$Om de ontstekingsreactie te remmen, werd Lia gedurende vijf dagen behandeld met intraveneus immuunglobuline (IVIg). Deze behandeling remt de productie van cytokine IL-2 door T-helpercellen. Cytokine IL-2 heeft een stimulerend effect op onder andere T-helpercellen zelf.$$, 'inline'),
  ('7047032c-9600-4997-837c-41e2e4c3aa87', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$Lia bekende regelmatig lachgas gebruikt te hebben; lachgas inactiveert vitamine B12, dat onmisbaar is voor myelinevorming in de cellen van Schwann$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context11.png$$,
   $$Na doorvragen van de neuroloog biechtte Lia op dat zij in de weken voorafgaand aan haar klachten regelmatig lachgas had gebruikt. Lachgasgebruik was een zeer plausibele verklaring voor haar klachten, omdat lachgas vitamine B12 inactiveert. Functioneel vitamine B12 is onmisbaar voor de vorming van myeline in de cellen van Schwann.$$, 'inline'),
  ('34a2be67-e259-44e1-bf3b-e6bd6b959abc', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$afbeelding 3: opname en transport van vitamine B12 uit de voeding via speeksel, maag, darm en darmepitheelcel naar het bloed, met de eiwitten haptocorrine, intrinsieke factor en transcobalamine$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context12.png$$,
   $$Afbeelding 3 laat op vereenvoudigde wijze zien hoe vitamine B12 uit de voeding via enkele omzettingen terecht kan komen in het bloed.$$, 'inline'),
  ('63e4b479-fae6-4d20-b5a8-7309612a3e3a', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$bij de opname van vitamine B12 zijn drie eiwitten betrokken: haptocorrine, intrinsieke factor en dierlijk eiwit uit de voeding$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context13.png$$,
   $$Bij opname van vitamine B12 zijn drie verschillende eiwitten betrokken: haptocorrine, intrinsieke factor en dierlijk eiwit uit de voeding. Elk van deze eiwitten heeft bepaalde eigenschappen die dat eiwit geschikt maken voor zijn rol in de vitamine-B12-opname.$$, 'inline'),
  ('6e774a9b-4c39-45e4-927f-ba46e67cb354', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$drie eigenschappen van de bij vitamine-B12-opname betrokken eiwitten, met betrekking tot afbraak door proteasen$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context14.png$$,
   $$Enkele eigenschappen van drie betrokken eiwitten zijn:
1 wordt alleen afgebroken door proteasen (eiwitsplitsende enzymen) uit de alvleesklier
2 wordt afgebroken door proteasen uit de maag en de alvleesklier
3 is bestand tegen proteasen uit de maag en de alvleesklier$$, 'inline'),
  ('652191d9-8ab4-42a8-8e4a-9a5e1e8932d9', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$afbeelding 4: vitamine B12 als cofactor bij de omzetting van methylmalonzuur naar succinyl-CoA en van homocysteïne naar methionine$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context15.png$$,
   $$Een bloedonderzoek kan geen onderscheid maken tussen functioneel en niet-functioneel vitamine B12. Daarom wordt het tekort aan functioneel vitamine B12 indirect aangetoond.
In afbeelding 4 is te zien dat twee vormen van vitamine B12 als cofactor betrokken zijn bij bepaalde enzymatische omzettingen.$$, 'inline'),
  ('bba7dd7e-f279-4ecb-8ddf-261a4e25a22b', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$het bloedonderzoek bij Lia toonde een tekort aan functioneel vitamine B12 aan$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context16.png$$,
   $$Het bloedonderzoek bij Lia toonde aan dat ze inderdaad een tekort had aan functioneel vitamine B12.$$, 'inline'),
  ('916c4614-6bf6-4c1a-bf98-551e034bc817', '443a91c4-52c8-43a5-9e5a-5a27666c46ff', $$na vitamine-B12-injecties verdwenen Lia''s symptomen snel; vitamine B12 kan ook als pil worden ingenomen$$,
   $$biologie-vwo-2022-i-lachgas-geen-onschuldige-partydrug-context17.png$$,
   $$Nadat Lia vitamine-B12-injecties kreeg, verdwenen de symptomen snel. Vitamine-B12 kan ook als pil worden ingenomen.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('51740ae3-eb69-4f3b-80ef-6a858302fb9d', 'c712e2b3-d498-4c4f-b734-d8250ee9c58d', 1,
   $$[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]$$::jsonb,
   $$["diurese", "vochtbalans", "vetverbranding", "gewichtsverlies"]$$::jsonb,
   $$Beredeneren dat een diuretisch middel vochtverlies veroorzaakt en niet per se vetverlies.$$,
